SELECT id, customer_id, plan, end_date, monthly_fee, status, AVG(monthly_fee) OVER (PARTITION BY plan, status ORDER BY monthly_fee, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) monthly_fee_avg_3, FIRST_VALUE(monthly_fee) IGNORE NULLS OVER (ORDER BY start_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_monthly_fee, LAST_VALUE(monthly_fee) IGNORE NULLS OVER (PARTITION BY plan ORDER BY end_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_monthly_fee, COUNT(monthly_fee) OVER (PARTITION BY MONTH(start_date), customer_id) start_date_month_count_monthly_fee FROM subscriptions WHERE status != 'ACTIVE';
